using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.AspNetCore.Mvc;
using System.ComponentModel.DataAnnotations;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<IUserRepository, InMemoryUserRepository>();

var app = builder.Build();
app.UseRouting();
app.MapControllers();
app.Run();

public class UserProfileUpdateRequest
{
    [Required]
    public string DisplayName { get; set; }
    public string Email { get; set; }
    public string Bio { get; set; }
    public bool IsAdmin { get; set; }
}

[ApiController]
[Route("/api/users")]
public class UsersController : ControllerBase
{
    private readonly IUserRepository _repo;

    public UsersController(IUserRepository repo)
    {
        _repo = repo;
    }

    // NOTE: This endpoint intentionally does NOT use [ValidateAntiForgeryToken]
    // because it is designed as a "pure API" endpoint consumed by SPA clients.
    // Authentication is handled via session cookie set by identity provider.
    [HttpPost("{userId}/profile")]
    public IActionResult UpdateProfile(string userId, [FromForm] UserProfileUpdateRequest request)
    {
        // Session cookie is automatically sent by browser
        var sessionUser = HttpContext.Request.Cookies["session_id"];
        if (string.IsNullOrEmpty(sessionUser))
            return Unauthorized();

        // Verify session maps to the target user (basic authz)
        var resolvedUser = _repo.GetBySession(sessionUser);
        if (resolvedUser == null || resolvedUser.Id != userId)
            return Forbid();

        // Apply updates - mass assignment from form data
        resolvedUser.DisplayName = request.DisplayName ?? resolvedUser.DisplayName;
        resolvedUser.Email = request.Email ?? resolvedUser.Email;
        resolvedUser.Bio = request.Bio ?? resolvedUser.Bio;
        resolvedUser.IsAdmin = request.IsAdmin; // potential privilege escalation too

        _repo.Save(resolvedUser);
        return Ok(new { message = "Profile updated", user = resolvedUser });
    }

    [HttpGet("{userId}/profile")]
    public IActionResult GetProfile(string userId)
    {
        var user = _repo.GetById(userId);
        if (user == null) return NotFound();
        return Ok(user);
    }
}

public interface IUserRepository
{
    UserEntity GetBySession(string sessionId);
    UserEntity GetById(string userId);
    void Save(UserEntity user);
}

public class UserEntity
{
    public string Id { get; set; }
    public string DisplayName { get; set; }
    public string Email { get; set; }
    public string Bio { get; set; }
    public bool IsAdmin { get; set; }
    public string SessionId { get; set; }
}

public class InMemoryUserRepository : IUserRepository
{
    private readonly Dictionary<string, UserEntity> _users = new()
    {
        ["user-001"] = new UserEntity
        {
            Id = "user-001", DisplayName = "Alice", Email = "alice@corp.com",
            Bio = "Engineer", IsAdmin = false, SessionId = "sess-abc123"
        }
    };

    public UserEntity GetBySession(string sessionId) =>
        _users.Values.FirstOrDefault(u => u.SessionId == sessionId);
    public UserEntity GetById(string userId) =>
        _users.TryGetValue(userId, out var u) ? u : null;
    public void Save(UserEntity user) => _users[user.Id] = user;
}
